head.script:
scwin.grid1_ongroupby = function(options) {
    return false;
};
scwin.grid1_groupbyFilterBoxFormatter = function(data) {
    var label = "";
    var labelArr = [];
    for (var i = 0; i < data.length; i++) {
        var s_label = "";
        var obj = data[i];
        var header = obj.header;
        var filter = obj.filter;
        for (var j = 0; j < filter.length; j++) {
            if (filter[j].gate)
                s_label = s_label + " " + filter[j].gate + " ";
            var values = filter[j].values;
            if (values.join)
                values = "[" + values.join(" ,") + "]";
            s_label = s_label + filter[j].operator + " " + values;
        }
        s_label = "(" + header + " " + s_label + ")";
        labelArr.push(s_label);
    }
    label = labelArr.join(" & ");
    return label;
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. Source 탭에서 grid1 의 foldAll 부분을 확인한다.
    //1. In the Source tab, check the foldAll portion of grid1.
    // verify step 1. foldAll = 'false'
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grid1').getAttribute('foldAll')", "false");
    // Test step 2. 브라우저에서 Run 또는 임의의 컬럼을 그룹화한다.
    //2. In the browser, group Run or any column.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    // verify step 2. 그룹화한 컬럼의 row들이 닫혀서 표현된다.
    //2. The rows of the grouped columns are closed.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_plus').length == 0", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
